// From nettle/macros.h

#define LE_READ_UINT32(p)                       \
(  (((uint32_t) (p)[3]) << 24)                  \
 | (((uint32_t) (p)[2]) << 16)                  \
 | (((uint32_t) (p)[1]) << 8)                   \
 |  ((uint32_t) (p)[0]))

#define LE_WRITE_UINT32(p, i)                   \
do {                                            \
  (p)[3] = ((i) >> 24) & 0xff;                  \
  (p)[2] = ((i) >> 16) & 0xff;                  \
  (p)[1] = ((i) >> 8) & 0xff;                   \
